import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import axiosInstance from '../../core/api/axiosConfig';
import {
  Box, Typography, Paper, Tabs, Tab, Button, IconButton, TextField,
  Dialog, DialogTitle, DialogContent, DialogActions, CircularProgress,
  Table, TableBody, TableCell, TableContainer, TableHead, TableRow, FormControl,
  InputLabel, Select, MenuItem,
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';

const ENDPOINTS = {
  departments: '/departments/',
  workLocations: '/work-locations/',
  jobTitles: '/job-titles/',
  insuranceLists: '/insurance-lists/',
  documentTypes: '/documents/types/',
};

const tabs = [
  { key: 'departments', label: 'دپارتمان‌ها' },
  { key: 'jobTitles', label: 'عناوین شغلی' },
  { key: 'workLocations', label: 'محل‌های استقرار' },
  { key: 'insuranceLists', label: 'لیست‌های بیمه' },
  { key: 'documentTypes', label: 'انواع مدارک' },
];

const EntityManager = ({ endpoint, fields = ['name', 'code'], extraFields = {}, defaultForm = {} }) => {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({});

  const { data, isLoading } = useQuery({
    queryKey: [endpoint],
    queryFn: () => axiosInstance.get(endpoint).then(r => r.data),
  });

  const saveMutation = useMutation({
    mutationFn: (payload) =>
      editing
        ? axiosInstance.patch(`${endpoint}${editing.id}/`, payload)
        : axiosInstance.post(endpoint, payload),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [endpoint] });
      setOpen(false);
      setEditing(null);
      setForm({});
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (id) => axiosInstance.delete(`${endpoint}${id}/`),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: [endpoint] }),
  });

  const handleOpen = (item = null) => {
    setEditing(item);
    setForm(item ? { ...item } : { ...defaultForm });
    setOpen(true);
  };

  const handleSave = () => saveMutation.mutate(form);

  const items = Array.isArray(data) ? data : data?.results || [];

  return (
    <Box>
      <Button variant="contained" startIcon={<AddIcon />} onClick={() => handleOpen()} sx={{ mb: 2 }}>
        افزودن
      </Button>
      <TableContainer component={Paper} variant="outlined">
        {isLoading ? (
          <Box sx={{ p: 3, textAlign: 'center' }}><CircularProgress size={24} /></Box>
        ) : (
          <Table size="small">
            <TableHead>
              <TableRow>
                {fields.map(f => <TableCell key={f} sx={{ fontWeight: 600 }}>{t(`employees.${f}`) || f}</TableCell>)}
                {Object.keys(extraFields).map(f => <TableCell key={f} sx={{ fontWeight: 600 }}>{extraFields[f]}</TableCell>)}
                <TableCell width={100}>{t('common.actions')}</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {items.length === 0 ? (
                <TableRow><TableCell colSpan={fields.length + Object.keys(extraFields).length + 1}>داده‌ای وجود ندارد</TableCell></TableRow>
              ) : (
                items.map(item => (
                  <TableRow key={item.id} hover>
                    {fields.map(f => <TableCell key={f}>{item[f]}</TableCell>)}
                    {Object.keys(extraFields).map(f => <TableCell key={f}>{item[f]}</TableCell>)}
                    <TableCell>
                      <IconButton size="small" onClick={() => handleOpen(item)}><EditIcon fontSize="small" /></IconButton>
                      <IconButton size="small" color="error" onClick={() => deleteMutation.mutate(item.id)}><DeleteIcon fontSize="small" /></IconButton>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        )}
      </TableContainer>

      <Dialog open={open} onClose={() => setOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>{editing ? 'ویرایش' : 'افزودن'}</DialogTitle>
        <DialogContent>
          {fields.map(f => (
            <TextField key={f} fullWidth size="small" label={t(`employees.${f}`) || f} value={form[f] || ''}
              onChange={e => setForm(p => ({ ...p, [f]: e.target.value }))} sx={{ mt: 1.5 }} />
          ))}
          {Object.keys(extraFields).map(f => (
            f === 'level' ? (
              <FormControl key={f} fullWidth size="small" sx={{ mt: 1.5 }}>
                <InputLabel>{extraFields[f]}</InputLabel>
                <Select value={form[f] || ''} label={extraFields[f]} onChange={e => setForm(p => ({ ...p, [f]: e.target.value }))}>
                  <MenuItem value="executive">مدیریتی</MenuItem>
                  <MenuItem value="expert">کارشناسی</MenuItem>
                  <MenuItem value="operational">عملیاتی</MenuItem>
                </Select>
              </FormControl>
            ) : (
              <TextField key={f} fullWidth size="small" label={extraFields[f]} value={form[f] || ''}
                onChange={e => setForm(p => ({ ...p, [f]: e.target.value }))} sx={{ mt: 1.5 }} multiline />
            )
          ))}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpen(false)}>{t('common.cancel')}</Button>
          <Button variant="contained" onClick={handleSave} disabled={saveMutation.isLoading}>
            {saveMutation.isLoading ? <CircularProgress size={20} /> : t('common.save')}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

const Settings = () => {
  const { t } = useTranslation();
  const [tabIndex, setTabIndex] = useState(0);

  return (
    <Box>
      <Typography variant="h4" gutterBottom>{t('nav.settings')}</Typography>
      <Paper sx={{ mb: 3 }}>
        <Tabs value={tabIndex} onChange={(e, v) => setTabIndex(v)} variant="scrollable" sx={{ px: 2, borderBottom: 1, borderColor: 'divider' }}>
          {tabs.map((tab, i) => <Tab key={tab.key} label={tab.label} />)}
        </Tabs>
        <Box sx={{ p: 3 }}>
          {tabIndex === 0 && <EntityManager endpoint={ENDPOINTS.departments} fields={['name', 'code']} />}
          {tabIndex === 1 && <EntityManager endpoint={ENDPOINTS.jobTitles} fields={['name', 'code']} extraFields={{ level: 'سطح' }} defaultForm={{ level: 'expert' }} />}
          {tabIndex === 2 && <EntityManager endpoint={ENDPOINTS.workLocations} fields={['name', 'code']} extraFields={{ description: 'توضیحات' }} />}
          {tabIndex === 3 && <EntityManager endpoint={ENDPOINTS.insuranceLists} fields={['name', 'code']} extraFields={{ description: 'توضیحات' }} />}
          {tabIndex === 4 && <EntityManager endpoint={ENDPOINTS.documentTypes} fields={['name', 'code']} />}
        </Box>
      </Paper>
    </Box>
  );
};

export default Settings;
